function M.example(level_index)
  local index = math.max(1, math.min(#Catalog.levels, tonumber(level_index) or 1))
  return verified[index]
end

function M.path_length(signature)
  local count = 0
  for _ in string.gmatch(signature or "", "[^|]+") do count = count + 1 end
  return count
end

function M.decode_token(token)
  token = tostring(token or "")
  local direction = string.sub(token, 1, 1)
  local sheep, wolves, people = 0, 0, 0
  for index = 2, #token do
    local digit = string.sub(token, index, index)
    if digit == "1" then sheep = sheep + 1
    elseif digit == "2" then wolves = wolves + 1
    elseif digit == "3" then people = people + 1 end
  end
  return { direction = direction, sheep = sheep, wolves = wolves, people = people }
end

return M
